import novamind_api as nm
# Check current targeted dev/ad/ops config from config_overrides
try:
    r = nm.query("SELECT * FROM config_overrides LIMIT 50")
    print("config_overrides rows:", len(r['rows']))
    for row in r['rows']:
        print(" ", row)
except Exception as e:
    print("config_overrides err:", e)
